mutation CreateItem($input: AddItemInput!) {
  itemMutation {
    addItem(input: $input) {
      id
      name
      units
      archived
    }
  }
}

mutation CreateOrder($input: AddOrderInput!) {
  orderMutation {
    addOrder(input: $input) {
      id
      createdAt
      updatedAt
      exception
    }
  }
}

mutation CreateUser($input: AddUserInput!) {
  userMutation {
    addUser(input: $input) {
      id
      email
      registeredAt
    }
  }
}

